-- v10 migration — True or False Showdown question bank.
-- Feeds the True or False Showdown game (last student standing).
-- Safe to run on live data (idempotent): existing statements are skipped.
--
-- answer = true  => the statement is TRUE.
-- Difficulty mix is ~1:3:1 (easy:medium:hard).

create table if not exists tf_questions (
  id uuid primary key default gen_random_uuid(),
  statement text not null,
  answer boolean not null,                     -- true = the statement is TRUE
  difficulty text not null default 'medium',   -- easy | medium | hard
  testament text,                              -- OT | NT | null
  reference text,                              -- e.g. 'John 3:16'
  explanation text,                            -- the correction / note, for the leader
  active boolean not null default true,
  created_at timestamptz not null default now()
);

-- Unique statement lets the seed below be re-run safely (on conflict do nothing).
create unique index if not exists tf_questions_statement_key on tf_questions (statement);
create index if not exists tf_questions_active_idx on tf_questions (active, difficulty);

-- RLS disabled to match the other game tables (see gtf_questions / game_prompts).
alter table tf_questions disable row level security;

-- Seed the 200-question bank. Re-running is safe: existing statements are skipped.
on conflict (statement) do nothing;
